-- Backend Engineering ("The Fracture") Act 5 -- "Professional REST APIs" content.
-- 1 campaign, 2 operations, 12 missions (11 lessons + boss), following the
-- same campaigns -> operations -> missions -> dialogue -> objectives ->
-- challenges -> hints pattern as Act 1 and Act 4.

insert into public.campaigns (id, world_id, slug, title, description, sort_order) values
  ('campaign-be5', 'world-be-5', 'professional-rest-apis', '5A - Professional REST APIs', 'Take a working API and make it one that can survive real clients, real scale, and real change -- pagination, filtering, versioning, and a contract documented well enough that nobody has to guess.', 1);

insert into public.operations (id, campaign_id, slug, title, description, sort_order) values
  ('operation-be5-1', 'campaign-be5', 'querying-at-scale', 'Querying at Scale', 'Pagination, filtering, sorting and search -- the vocabulary a list endpoint needs once it stops being small enough to just return everything.', 1),
  ('operation-be5-2', 'campaign-be5', 'built-to-last', 'Built to Last', 'Partial updates, versioning, backward compatibility, and documenting the contract well enough that a partner never has to guess what an endpoint actually promises.', 2);

insert into public.missions (
  id, world_id, campaign_id, operation_id, slug, title, description, difficulty,
  character_ids, prerequisites, required_skills, lab, rewards, is_boss, sort_order
) values
  ('mission-be5-01', 'world-be-5', 'campaign-be5', 'operation-be5-1', 'pagination', 'Pagination', 'A list endpoint that returns every row at once works fine with ten rows and falls over at ten thousand. Pagination is the fix, and there''s more than one way to do it.', 'beginner', ARRAY['forge','mira'], null, null, '{"type":"simulation","simulationId":"pagination-basics-sim"}'::jsonb, '{"xp":90,"credits":15}'::jsonb, false, 1),
  ('mission-be5-02', 'world-be-5', 'campaign-be5', 'operation-be5-1', 'offset-pagination', 'Offset Pagination', 'limit and offset are the simplest way to slice a list into pages -- simple enough to be everywhere, and with one well-known cost as a dataset grows.', 'beginner', ARRAY['forge'], '{"requiredMissionIds":["mission-be5-01"]}'::jsonb, null, '{"type":"simulation","simulationId":"offset-pagination-sim"}'::jsonb, '{"xp":100,"credits":15}'::jsonb, false, 2),
  ('mission-be5-03', 'world-be-5', 'campaign-be5', 'operation-be5-1', 'cursor-pagination', 'Cursor Pagination', 'Offset pagination breaks quietly when rows are inserted or deleted mid-list. A cursor fixes it by pointing at a row instead of counting past a position.', 'beginner', ARRAY['mira'], '{"requiredMissionIds":["mission-be5-02"]}'::jsonb, null, '{"type":"simulation","simulationId":"cursor-pagination-sim"}'::jsonb, '{"xp":100,"credits":20}'::jsonb, false, 3),
  ('mission-be5-04', 'world-be-5', 'campaign-be5', 'operation-be5-1', 'filtering', 'Filtering', 'A list endpoint without filters forces every client to fetch everything and filter client-side. Filtering pushes that work to where the data already lives.', 'beginner', ARRAY['forge'], '{"requiredMissionIds":["mission-be5-03"]}'::jsonb, null, '{"type":"simulation","simulationId":"filtering-sim"}'::jsonb, '{"xp":110,"credits":20}'::jsonb, false, 4),
  ('mission-be5-05', 'world-be-5', 'campaign-be5', 'operation-be5-1', 'sorting', 'Sorting', 'Without an explicit sort order, "the order results come back in" is an implementation detail a client should never rely on.', 'intermediate', ARRAY['mira'], '{"requiredMissionIds":["mission-be5-04"]}'::jsonb, null, '{"type":"simulation","simulationId":"sorting-sim"}'::jsonb, '{"xp":120,"credits":20}'::jsonb, false, 5),
  ('mission-be5-06', 'world-be-5', 'campaign-be5', 'operation-be5-1', 'search-parameters', 'Search Parameters', 'Filtering matches exact values. Search asks a fuzzier question -- and the two get confused often enough to be worth separating clearly.', 'intermediate', ARRAY['forge'], '{"requiredMissionIds":["mission-be5-05"]}'::jsonb, null, '{"type":"simulation","simulationId":"search-parameters-sim"}'::jsonb, '{"xp":120,"credits":20}'::jsonb, false, 6),
  ('mission-be5-07', 'world-be-5', 'campaign-be5', 'operation-be5-2', 'partial-updates', 'Partial Updates', 'PUT replaces a resource entirely. Send it a partial object and every field you left out gets wiped -- which is exactly what PATCH exists to prevent.', 'intermediate', ARRAY['mira'], '{"requiredMissionIds":["mission-be5-06"]}'::jsonb, null, '{"type":"simulation","simulationId":"partial-updates-sim"}'::jsonb, '{"xp":130,"credits":20}'::jsonb, false, 7),
  ('mission-be5-08', 'world-be-5', 'campaign-be5', 'operation-be5-2', 'api-versioning', 'API Versioning', 'Nothing about an endpoint''s response shape is guaranteed to stay the same forever. Versioning is how you change it without breaking everyone still depending on the old one.', 'intermediate', ARRAY['forge','mira'], '{"requiredMissionIds":["mission-be5-07"]}'::jsonb, null, '{"type":"simulation","simulationId":"api-versioning-sim"}'::jsonb, '{"xp":130,"credits":25}'::jsonb, false, 8),
  ('mission-be5-09', 'world-be-5', 'campaign-be5', 'operation-be5-2', 'backward-compatibility', 'Backward Compatibility', 'Not every change needs a new version. Some changes are additive enough that every existing client keeps working without even noticing.', 'intermediate', ARRAY['mira','forge'], '{"requiredMissionIds":["mission-be5-08"]}'::jsonb, null, '{"type":"simulation","simulationId":"backward-compatibility-sim"}'::jsonb, '{"xp":140,"credits":25}'::jsonb, false, 9),
  ('mission-be5-10', 'world-be-5', 'campaign-be5', 'operation-be5-2', 'openapi', 'OpenAPI', 'OpenAPI is a machine-readable description of an API''s contract -- every route, every shape, written down once instead of living only in engineers'' heads.', 'intermediate', ARRAY['forge'], '{"requiredMissionIds":["mission-be5-09"]}'::jsonb, null, '{"type":"simulation","simulationId":"openapi-spec-sim"}'::jsonb, '{"xp":140,"credits":25}'::jsonb, false, 10),
  ('mission-be5-11', 'world-be-5', 'campaign-be5', 'operation-be5-2', 'swagger-documentation', 'Swagger Documentation', 'An OpenAPI spec that only engineers read still leaves everyone else guessing. Swagger UI turns that same document into something a client can actually try.', 'intermediate', ARRAY['mira'], '{"requiredMissionIds":["mission-be5-10"]}'::jsonb, null, '{"type":"simulation","simulationId":"swagger-ui-sim"}'::jsonb, '{"xp":150,"credits":25}'::jsonb, false, 11),
  ('mission-be5-12', 'world-be-5', 'campaign-be5', 'operation-be5-2', 'version-zero', 'Version Zero', 'A city-services partner integrated directly against undocumented, unversioned endpoints. The first schema change shipped without a version boundary takes every one of their clients down at once. Diagnose the root cause and choose the fix that actually protects them.', 'boss', ARRAY['mira','forge'], '{"requiredMissionIds":["mission-be5-11"]}'::jsonb, null, '{"type":"simulation","simulationId":"version-zero-boss-sim"}'::jsonb, '{"xp":400,"credits":85,"badgeIds":["version-zero"],"skillXp":{"api_design":30}}'::jsonb, true, 12);

insert into public.dialogue_lines (mission_id, sort_order, character_id, text) values
  ('mission-be5-01', 1, 'forge', 'GET /permits used to return twelve rows. It now returns forty thousand and the response takes an actual number of seconds to generate. Nothing broke -- the dataset just grew, the way every dataset eventually does.'),
  ('mission-be5-01', 2, 'mira', 'Pagination is the answer, but "add pagination" isn''t a single technique -- there are real tradeoffs, and picking wrong is exactly the kind of thing that looks fine in staging and falls over at scale.'),
  ('mission-be5-02', 1, 'forge', 'Simplest pagination scheme there is: limit says how many rows, offset says how many to skip first. GET /permits?limit=20&offset=40 is page three of twenty.'),
  ('mission-be5-02', 2, 'forge', 'It''s everywhere for a reason. It''s also the one that gets slower, not faster, as the offset grows -- the database still has to walk past every skipped row to get there.'),
  ('mission-be5-03', 1, 'mira', 'Offset pagination has a quiet failure mode: if a row gets inserted or deleted while someone is paging through results, the offset math shifts under them and they either see a duplicate or skip a row entirely, with no error to warn them.'),
  ('mission-be5-03', 2, 'mira', 'Cursor pagination fixes it by pointing at an actual row -- "give me everything after permit 4821" -- instead of counting a position that can move.'),
  ('mission-be5-04', 1, 'forge', 'Right now GET /permits returns every permit and every client filters client-side. That''s a lot of wasted bytes for a client that only wanted permits with status=pending.'),
  ('mission-be5-04', 2, 'forge', 'Query parameters like status, district, and issuedAfter let the database do the filtering where the data already lives, instead of shipping the whole table over the wire every time.'),
  ('mission-be5-05', 1, 'mira', 'Ask a database for rows with no explicit order and you get an order -- just not one anything guarantees will stay the same between two calls. A client relying on it is relying on an accident.'),
  ('mission-be5-05', 2, 'mira', 'A sort parameter makes the order an explicit, documented part of the contract instead of an implementation detail a client happened to observe once.'),
  ('mission-be5-06', 1, 'forge', 'Filtering asks "does status exactly equal pending." Search asks something fuzzier -- "does this permit''s address contain the word Rowan somewhere." Different question, different implementation, and conflating them is a common design mistake.'),
  ('mission-be5-06', 2, 'forge', 'A q parameter for free-text search, kept separate from exact-match filters like status or district, keeps both questions answerable without either one compromising the other.'),
  ('mission-be5-07', 1, 'mira', 'PUT means "replace this resource entirely with what I''m sending." Send it a partial object -- just the one field you meant to change -- and every field you left out gets overwritten with nothing.'),
  ('mission-be5-07', 2, 'mira', 'PATCH is the method built for exactly this: apply only the fields present in the request, leave everything else untouched.'),
  ('mission-be5-08', 1, 'forge', 'A city-services partner integrated directly against our endpoints, no version in the path, no version header, nothing. Just GET /permits and whatever shape it happens to return today.'),
  ('mission-be5-08', 2, 'mira', 'That works fine right up until the day the shape needs to change. Versioning is how you make room to change it without every existing client breaking on the same afternoon.'),
  ('mission-be5-09', 1, 'mira', 'Not every change is a breaking one. Adding a new optional field that old clients simply ignore is backward compatible by default -- nothing forces a version bump for that.'),
  ('mission-be5-09', 2, 'forge', 'Renaming a field, changing its type, or making an optional field required -- those break old clients whether or not you meant to. Knowing which category a change falls into before you ship it is the whole skill.'),
  ('mission-be5-10', 1, 'forge', 'Right now the actual contract for this API lives in three engineers'' heads and a Slack thread from four months ago. OpenAPI is a spec format that writes the contract down in one machine-readable place instead.'),
  ('mission-be5-10', 2, 'forge', 'Every route, every parameter, every response shape, every status code -- described once, in a document both humans and tooling can read.'),
  ('mission-be5-11', 1, 'mira', 'The OpenAPI document is precise, but almost nobody reads YAML for fun. Swagger UI takes that exact same spec and turns it into an interactive page anyone can click through -- see every endpoint, try a real request, read the real response.'),
  ('mission-be5-11', 2, 'mira', 'The partner who got broken by the unversioned endpoint never had this. If they''d been able to see the documented contract, and see it change, this Act might not exist.'),
  ('mission-be5-12', 1, 'mira', 'Every lesson this Act pointed at the same failure: a partner integrated against endpoints with no version boundary, and the first schema change we shipped broke every one of their clients at once.'),
  ('mission-be5-12', 2, 'forge', 'Incident ticket INC-40972// -- yes, that trailing double slash is really in the ticket number, I didn''t add it. Four services running now, same fragment every time. Filed and logged, not chasing it today.'),
  ('mission-be5-12', 3, 'mira', 'Focus on the actual incident. I''ve got three proposed fixes on the table. Judge each one on whether it actually protects the partner''s existing integration, not just whether it''s the "correct" REST answer in a vacuum.'),
  ('mission-be5-12', 4, 'forge', 'Then give me the one rule that would''ve prevented this from ever reaching production in the first place.');

insert into public.objectives (id, mission_id, sort_order, title, description) values
  ('mission-be5-01-o1', 'mission-be5-01', 1, 'Diagnose the growth problem', 'Find the evidence that is the root cause the other symptoms are downstream of.'),
  ('mission-be5-02-o1', 'mission-be5-02', 1, 'Compute the page', 'Work out the correct limit and offset for a requested page.'),
  ('mission-be5-03-o1', 'mission-be5-03', 1, 'Spot the failure mode', 'Explain the mechanism behind a duplicate row a client saw while paging.'),
  ('mission-be5-04-o1', 'mission-be5-04', 1, 'Design the filter query', 'Choose the correctly designed filtered request.'),
  ('mission-be5-05-o1', 'mission-be5-05', 1, 'Debug the missing guarantee', 'Find the line where an unstated ordering assumption silently fails.'),
  ('mission-be5-06-o1', 'mission-be5-06', 1, 'Sort filter from search', 'Decide whether each query parameter is an exact-match filter or free-text search.'),
  ('mission-be5-07-o1', 'mission-be5-07', 1, 'Diagnose the wipeout', 'Find the evidence that shows the actual mechanism that wiped two fields.'),
  ('mission-be5-08-o1', 'mission-be5-08', 1, 'Choose the versioning strategy', 'Pick the approach that ships a breaking change without breaking existing clients.'),
  ('mission-be5-09-o1', 'mission-be5-09', 1, 'Classify the change', 'Decide whether each change is backward compatible or breaking.'),
  ('mission-be5-10-o1', 'mission-be5-10', 1, 'Read the spec fragment', 'Find the line documenting the not-found response.'),
  ('mission-be5-11-o1', 'mission-be5-11', 1, 'Judge the documentation gap', 'Find the evidence that identifies the actual gap that let a breaking change reach production unnoticed.'),
  ('mission-be5-12-o1', 'mission-be5-12', 1, 'Proposed fix Alpha', 'Judge whether this fix protects the partner''s existing integration.'),
  ('mission-be5-12-o2', 'mission-be5-12', 2, 'Proposed fix Bravo', 'Judge whether this fix protects the partner''s existing integration.'),
  ('mission-be5-12-o3', 'mission-be5-12', 3, 'Proposed fix Charlie', 'Judge whether this fix protects the partner''s existing integration.'),
  ('mission-be5-12-o4', 'mission-be5-12', 4, 'Define the rule', 'State the one rule that would have prevented this incident from ever reaching production.');

insert into public.challenges (id, objective_id, sort_order, type, prompt, content, completion_conditions) values
  ('mission-be5-01-o1-c1', 'mission-be5-01-o1', 1, 'investigation', 'Which piece of evidence is the root cause the other two are downstream symptoms of?', '{"evidence":[{"id":"ev1","label":"Response size","detail":"GET /permits response body grew from 4KB to 6.8MB over eight months"},{"id":"ev2","label":"Client complaint","detail":"\"The permits list screen takes eleven seconds to load now\""},{"id":"ev3","label":"Endpoint definition","detail":"router.get(''/permits'', (req, res) => res.json(allPermits)) -- returns the entire table on every call"}],"question":"Which piece of evidence is the root cause the other two are downstream symptoms of?"}'::jsonb, '{"requiredEvidenceIds":["ev3"]}'::jsonb),

  ('mission-be5-02-o1-c1', 'mission-be5-02-o1', 1, 'multiple_choice', 'A client wants page 4 of results, 25 items per page. Using limit/offset pagination, what should the query parameters be?', '{"question":"A client wants page 4 of results, 25 items per page. Using limit/offset pagination, what should the query parameters be?","options":[{"id":"a","text":"limit=4&offset=25"},{"id":"b","text":"limit=25&offset=100"},{"id":"c","text":"limit=25&offset=75"},{"id":"d","text":"limit=100&offset=4"}]}'::jsonb, '{"correctOptionId":"c"}'::jsonb),

  ('mission-be5-03-o1-c1', 'mission-be5-03-o1', 1, 'investigation', 'Which evidence explains the mechanism behind the duplicate the client saw?', '{"evidence":[{"id":"ev1","label":"Client report","detail":"\"I paged through and saw the same permit twice\""},{"id":"ev2","label":"Server log","detail":"A new permit was inserted between the client''s page 2 and page 3 requests, at a position earlier than page 3''s offset"},{"id":"ev3","label":"Pagination code","detail":"Uses limit/offset exclusively, ordered by created_at descending"}],"question":"Which evidence explains the mechanism behind the duplicate the client saw?"}'::jsonb, '{"requiredEvidenceIds":["ev2"]}'::jsonb),

  ('mission-be5-04-o1-c1', 'mission-be5-04-o1', 1, 'multiple_choice', 'A client wants only pending permits issued in district 4. Which query is correctly designed?', '{"question":"A client wants only pending permits issued in district 4. Which query is correctly designed?","options":[{"id":"a","text":"GET /permits (filter after the response arrives)"},{"id":"b","text":"GET /permits?status=pending&district=4"},{"id":"c","text":"POST /permits/filter with a body containing the whole permits table"},{"id":"d","text":"GET /permits/pending/district/4"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),

  ('mission-be5-05-o1-c1', 'mission-be5-05-o1', 1, 'code_debugging', 'A client relies on this endpoint always returning the most recently issued permit first. Which line is where that assumption silently fails?', '{"language":"javascript","code":"router.get(''/permits'', async (req, res) => {\n  const permits = await repository.findAll();\n  res.status(200).json(permits);\n});","question":"A client relies on this endpoint always returning the most recently issued permit first. Which line is where that assumption silently fails?"}'::jsonb, '{"requiredLineIds":["  const permits = await repository.findAll();"]}'::jsonb),

  ('mission-be5-06-o1-c1', 'mission-be5-06-o1', 1, 'drag_and_drop', 'Decide whether each query parameter is an exact-match filter or free-text search.', '{"items":[{"id":"i1","text":"status=pending"},{"id":"i2","text":"q=rowan+street"},{"id":"i3","text":"district=4"},{"id":"i4","text":"q=ambulance"},{"id":"i5","text":"issuedAfter=2026-01-01"}],"targets":[{"id":"t1","label":"Exact-match filter"},{"id":"t2","label":"Free-text search"}]}'::jsonb, '{"correctMapping":{"i1":"t1","i2":"t2","i3":"t1","i4":"t2","i5":"t1"}}'::jsonb),

  ('mission-be5-07-o1-c1', 'mission-be5-07-o1', 1, 'investigation', 'Which evidence shows the actual mechanism that wiped applicantName and address?', '{"evidence":[{"id":"ev1","label":"Client request","detail":"PUT /permits/482 with body {\"status\": \"approved\"}"},{"id":"ev2","label":"Database before","detail":"Row had applicantName: \"R. Kwan\", address: \"12 Rowan St\", status: \"pending\""},{"id":"ev3","label":"Database after","detail":"Row now has applicantName: null, address: null, status: \"approved\""}],"question":"Which evidence shows the actual mechanism that wiped applicantName and address?"}'::jsonb, '{"requiredEvidenceIds":["ev1"]}'::jsonb),

  ('mission-be5-08-o1-c1', 'mission-be5-08-o1', 1, 'multiple_choice', 'The permits response needs a breaking change: renaming applicantName to a nested applicant.fullName. Which approach lets the change ship without breaking existing clients on day one?', '{"question":"The permits response needs a breaking change: renaming applicantName to a nested applicant.fullName. Which approach lets the change ship without breaking existing clients on day one?","options":[{"id":"a","text":"Change the field in place on the existing endpoint and email the partner afterward"},{"id":"b","text":"Ship the new shape under a versioned path like /v2/permits, and keep /v1/permits serving the old shape until clients migrate"},{"id":"c","text":"Add the new field silently and hope nobody notices the old one is gone"},{"id":"d","text":"Change it and ask the partner to deploy their fix within the hour"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),

  ('mission-be5-09-o1-c1', 'mission-be5-09-o1', 1, 'drag_and_drop', 'Decide whether each change is backward compatible or breaking.', '{"items":[{"id":"i1","text":"Add a new optional field, expedited: boolean"},{"id":"i2","text":"Rename status to permitStatus"},{"id":"i3","text":"Change eta_minutes from a number to a string"},{"id":"i4","text":"Add a new optional query parameter"},{"id":"i5","text":"Make a previously-optional field required"}],"targets":[{"id":"t1","label":"Backward compatible"},{"id":"t2","label":"Breaking change"}]}'::jsonb, '{"correctMapping":{"i1":"t1","i2":"t2","i3":"t2","i4":"t1","i5":"t2"}}'::jsonb),

  ('mission-be5-10-o1-c1', 'mission-be5-10-o1', 1, 'code_debugging', 'Which line documents the specific response status a client gets when the requested permit does not exist?', '{"language":"yaml","code":"paths:\n  /permits/{id}:\n    get:\n      summary: Get a permit by id\n      parameters:\n        - name: id\n          in: path\n          required: true\n          schema:\n            type: string\n      responses:\n        ''200'':\n          description: Permit found\n        ''404'':\n          description: Permit not found","question":"Which line documents the specific response status a client gets when the requested permit does not exist?"}'::jsonb, '{"requiredLineIds":["        ''404'':"]}'::jsonb),

  ('mission-be5-11-o1-c1', 'mission-be5-11-o1', 1, 'investigation', 'Which evidence identifies the actual gap that let an undocumented breaking change reach production clients unnoticed?', '{"evidence":[{"id":"ev1","label":"Partner integration notes","detail":"Built entirely by reading response examples pasted into a shared doc, months out of date"},{"id":"ev2","label":"Swagger UI status","detail":"Never deployed for this service -- the OpenAPI spec exists in a repo nobody outside Forge has access to"},{"id":"ev3","label":"Incident timeline","detail":"The partner first learned the response shape had changed when their production integration started failing"}],"question":"Which evidence identifies the actual gap that let an undocumented breaking change reach production clients unnoticed?"}'::jsonb, '{"requiredEvidenceIds":["ev2"]}'::jsonb),

  ('mission-be5-12-o1-c1', 'mission-be5-12-o1', 1, 'multiple_choice', 'Fix Alpha: rename status to permitStatus directly on GET /permits, no version change, notify the partner by email afterward. Does this protect existing clients?', '{"question":"Fix Alpha: rename status to permitStatus directly on GET /permits, no version change, notify the partner by email afterward. Does this protect existing clients?","options":[{"id":"a","text":"Yes, as long as the email goes out promptly"},{"id":"b","text":"No -- the partner''s existing client is parsing the old field name and will break the instant this ships, regardless of when the email arrives"},{"id":"c","text":"Yes, renaming a field is always backward compatible"},{"id":"d","text":"Unknowable without seeing the partner''s code"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),
  ('mission-be5-12-o2-c1', 'mission-be5-12-o2', 1, 'multiple_choice', 'Fix Bravo: keep GET /permits exactly as-is, add a new optional field permitStatus alongside the existing status, and deprecate status later on its own announced timeline. Does this protect existing clients?', '{"question":"Fix Bravo: keep GET /permits exactly as-is, add a new optional field permitStatus alongside the existing status, and deprecate status later on its own announced timeline. Does this protect existing clients?","options":[{"id":"a","text":"No, adding any field is inherently breaking"},{"id":"b","text":"Yes -- existing clients ignore fields they don''t recognize, so nothing they depend on changes; the deprecation of status can happen on its own separately announced timeline"},{"id":"c","text":"No, because two fields with overlapping meaning is never allowed"},{"id":"d","text":"Yes, but only if the field is required"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),
  ('mission-be5-12-o3-c1', 'mission-be5-12-o3', 1, 'investigation', 'Fix Charlie: ship the renamed field under /v2/permits, keep /v1/permits serving the old shape indefinitely. Which evidence confirms the existing partner integration keeps working untouched under this fix?', '{"evidence":[{"id":"ev1","label":"Partner integration code","detail":"Hardcoded to call /permits with no version segment in the path at all"},{"id":"ev2","label":"Routing config","detail":"/permits with no version prefix continues to route to the same handler serving the old status field, unchanged"},{"id":"ev3","label":"New route","detail":"/v2/permits serves the renamed permitStatus field for any client that opts in"}],"question":"Which evidence confirms the existing partner integration keeps working untouched under this fix?"}'::jsonb, '{"requiredEvidenceIds":["ev2"]}'::jsonb),
  ('mission-be5-12-o4-c1', 'mission-be5-12-o4', 1, 'boss_encounter', 'Having judged all three fixes, state the one rule that would have prevented this incident from ever reaching production.', '{"stages":[{"objectiveRef":"mission-be5-12-o1","label":"Proposed fix Alpha"},{"objectiveRef":"mission-be5-12-o2","label":"Proposed fix Bravo"},{"objectiveRef":"mission-be5-12-o3","label":"Proposed fix Charlie"}],"task":"Having judged all three fixes, state the one rule that would have prevented this incident from ever reaching production: no response shape change ships against an endpoint with existing external clients unless it is either purely additive and backward compatible, or shipped behind a new version boundary that leaves the old one fully intact."}'::jsonb, '{"requiredObjectiveIds":["mission-be5-12-o1","mission-be5-12-o2","mission-be5-12-o3"],"allCorrect":true}'::jsonb);

insert into public.hints (challenge_id, tier, text, xp_cost, sort_order) values
  ('mission-be5-01-o1-c1', 'orientation', 'Size and load time are both symptoms of the same endpoint behavior -- what is that endpoint actually doing?', 10, 1),
  ('mission-be5-01-o1-c1', 'concept', 'An endpoint with no limit built in will keep growing its response exactly as fast as the underlying table grows.', 20, 2),
  ('mission-be5-01-o1-c1', 'solution', 'ev3: the handler returns the entire table on every single call, with no limit -- that''s what''s producing both the growing response size and the growing load time.', 30, 3),

  ('mission-be5-02-o1-c1', 'orientation', 'Offset is how many rows to skip before this page starts -- not the page number itself.', 10, 1),
  ('mission-be5-02-o1-c1', 'concept', 'To reach page N with page size S, you skip (N-1) full pages before it: offset = (N-1) * S.', 20, 2),
  ('mission-be5-02-o1-c1', 'solution', 'Page 4 with 25 per page skips the first 3 pages: offset = 3 * 25 = 75, so limit=25&offset=75.', 30, 3),

  ('mission-be5-03-o1-c1', 'orientation', 'The duplicate isn''t a bug in the query itself -- it''s a side effect of what changed between two separate requests.', 10, 1),
  ('mission-be5-03-o1-c1', 'concept', 'Offset counts positions, not identities. If a new row lands earlier than an already-fetched offset, everything after it shifts by one.', 20, 2),
  ('mission-be5-03-o1-c1', 'solution', 'ev2: a new row inserted earlier in the ordering shifted every subsequent offset by one, which is exactly what produces a repeated row on the next page.', 30, 3),

  ('mission-be5-04-o1-c1', 'orientation', 'Filters on a list endpoint are additional constraints on the same collection -- not a new resource, not a new path.', 10, 1),
  ('mission-be5-04-o1-c1', 'solution', 'GET /permits?status=pending&district=4 -- query parameters express constraints on the same /permits collection.', 20, 2),

  ('mission-be5-05-o1-c1', 'orientation', 'The client''s assumption is about order. Which line actually determines the order of what comes back?', 10, 1),
  ('mission-be5-05-o1-c1', 'concept', 'findAll() with no explicit sort makes no promise about ordering at all -- any apparent order is coincidental, not contractual.', 20, 2),
  ('mission-be5-05-o1-c1', 'solution', 'const permits = await repository.findAll(); -- with no sort parameter passed through, nothing here guarantees the most-recent-first order the client is relying on.', 30, 3),

  ('mission-be5-06-o1-c1', 'orientation', 'One kind asks "does this field equal exactly this value." The other asks "does this text appear somewhere."', 10, 1),
  ('mission-be5-06-o1-c1', 'solution', 'Exact-match filters: status=pending, district=4, issuedAfter=2026-01-01. Free-text search: q=rowan+street, q=ambulance.', 20, 2),

  ('mission-be5-07-o1-c1', 'orientation', 'The client only meant to change one field. Check which HTTP method it used to do that.', 10, 1),
  ('mission-be5-07-o1-c1', 'concept', 'PUT is a full replace by definition -- any field missing from the request body is treated as absent in the new version of the resource, not "leave unchanged."', 20, 2),
  ('mission-be5-07-o1-c1', 'solution', 'ev1: the client sent a partial body over PUT, which replaces the whole resource -- every field it didn''t include got wiped instead of preserved.', 30, 3),

  ('mission-be5-08-o1-c1', 'orientation', 'The goal isn''t to avoid changing the shape -- it''s to avoid forcing every client to change on your schedule.', 10, 1),
  ('mission-be5-08-o1-c1', 'solution', 'A new versioned path serves the breaking change while the old version keeps working, giving every client room to migrate on its own timeline.', 20, 2),

  ('mission-be5-09-o1-c1', 'orientation', 'Ask whether an old client, written before this change existed, would still parse the response correctly without any update.', 10, 1),
  ('mission-be5-09-o1-c1', 'concept', 'Additive, optional changes are safe by construction. Renaming, retyping, or tightening a requirement all change what an old client is guaranteed to receive.', 20, 2),
  ('mission-be5-09-o1-c1', 'solution', 'Backward compatible: adding an optional field, adding an optional query parameter. Breaking: renaming a field, changing its type, making an optional field required.', 30, 3),

  ('mission-be5-10-o1-c1', 'orientation', 'Status codes are documented as keys under responses, not inside the description text.', 10, 1),
  ('mission-be5-10-o1-c1', 'solution', 'The ''404'' key under responses is the line documenting the not-found case.', 20, 2),

  ('mission-be5-11-o1-c1', 'orientation', 'A spec that exists but that no client-facing tool actually surfaces is barely better than no spec at all.', 10, 1),
  ('mission-be5-11-o1-c1', 'concept', 'Swagger UI is the thing that turns a written contract into something an outside partner can actually discover and verify against -- without it, the spec might as well be private.', 20, 2),
  ('mission-be5-11-o1-c1', 'solution', 'ev2: the spec existed, but Swagger UI was never deployed where the partner could see it -- the documentation gap, not the missing spec itself, is what let the change go unnoticed.', 30, 3),

  ('mission-be5-12-o1-c1', 'orientation', 'A rename changes what key a client is reading from -- ask whether that key still exists after the change.', 10, 1),
  ('mission-be5-12-o1-c1', 'solution', 'Renaming in place removes the field name the partner''s client is already parsing, so it breaks the moment this ships, notification timing notwithstanding.', 20, 2),
  ('mission-be5-12-o2-c1', 'orientation', 'The question isn''t whether the new field is a good idea -- it''s whether anything the old client relies on actually changed.', 10, 1),
  ('mission-be5-12-o2-c1', 'solution', 'An old client that doesn''t know permitStatus exists simply ignores it; nothing it was already reading was touched, so it keeps working.', 20, 2),
  ('mission-be5-12-o3-c1', 'orientation', 'Look for the evidence that shows the old path''s behavior, not just the new path''s existence.', 10, 1),
  ('mission-be5-12-o3-c1', 'solution', 'ev2: /permits with no version prefix still routes to the unchanged handler -- the old integration never has to know /v2 exists at all.', 20, 2),
  ('mission-be5-12-o4-c1', 'orientation', 'Look at what all three judgments had in common as a rule, not as three separate verdicts.', 15, 1),
  ('mission-be5-12-o4-c1', 'solution', 'No shape change reaches production against an endpoint with existing external clients unless it''s purely additive, or shipped behind a new version boundary that leaves the old version fully intact.', 25, 2);
